insert into public.country_occupation_metric_snapshots (profile_key,as_of_date,shortage_component,vacancy_intensity_component,employer_diversity_component,vacancy_trend_component,entry_level_component,salary_component,growth_component,visa_component,entry_burden_component,opportunity_score,score_methodology_version,score_status,score_evidence,source_checked_at) values
('JP:early-childhood-teacher','2026-08-10',0,0,0,0,10,0,0,0,1,11,'career-opportunity-jp-v1','provisional',jsonb_build_object('classification_scope','2022 MHLW 029-02 directly classifies 幼稚園教員 and is kept separate from 保育士 029-01.','entry_level_basis','An approved Japanese child-education programme is retained as a direct study pathway where the institution offers the required teacher-training curriculum.','qualification_note','Teaching in a kindergarten requires the applicable 幼稚園教諭免許状; degree completion alone is not the licence.','market_scope','No exact recurring comparable 029-02 market series is scored in the foundation phase.','visa_scope','No occupation-specific visa credit is assigned.'),'2026-08-10'),
('JP:primary-school-teacher','2026-08-10',0,0,0,0,10,0,0,0,1,11,'career-opportunity-jp-v1','provisional',jsonb_build_object('classification_scope','2022 MHLW 031-01 directly classifies 小学校教員.','entry_level_basis','An approved child-education programme is retained as a direct academic pathway only where it supports the applicable teacher-training route.','qualification_note','A school teacher must hold the licence corresponding to the school type; public-school employment also normally requires the relevant hiring selection.','market_scope','No exact recurring comparable 031-01 market series is scored.','visa_scope','No occupation-specific visa credit is assigned.'),'2026-08-10'),
('JP:secondary-school-teacher','2026-08-10',0,0,0,0,10,0,0,0,1,11,'career-opportunity-jp-v1','provisional',jsonb_build_object('classification_scope','The canonical Secondary School Teacher spans 031-02 中学校教員, 031-04 高等学校教員 and 031-05 中等教育学校教員 rather than one exact small-classification code.','entry_level_basis','The currently reviewed Japanese programme link is retained only as related because a Japanese-language teaching programme is not automatically a Japanese middle/high-school teacher-licensing programme.','qualification_note','Middle and high school teaching requires the applicable school-type and subject teacher licence; programme title alone does not establish licensure.','market_scope','The three school-type classifications are not merged into a fabricated exact market series.','visa_scope','No occupation-specific visa credit is assigned.'),'2026-08-10'),
('JP:special-education-teacher','2026-08-10',0,0,0,0,8,0,0,0,1,9,'career-opportunity-jp-v1','provisional',jsonb_build_object('classification_scope','2022 MHLW 031-06 directly classifies 特別支援学校教員.','entry_level_basis','The reviewed special-needs-education programme is retained as a direct academic pathway subject to the applicable Japanese teacher-licensing curriculum.','qualification_note','MEXT guidance requires a foundational kindergarten, elementary, middle or high-school teacher licence plus required special-support education credits and an application for the 特別支援学校教諭免許状.','market_scope','No exact recurring comparable 031-06 market series is scored.','visa_scope','No occupation-specific visa credit is assigned.'),'2026-08-10'),
('JP:social-worker','2026-08-10',0,0,0,0,10,0,0,0,1,11,'career-opportunity-jp-v1','provisional',jsonb_build_object('classification_scope','社会福祉士 work appears across 049-02 welfare consultation, 049-03 elder-welfare guidance, 049-04 disability-welfare guidance, 049-05 child-welfare guidance and 049-99 other professional welfare settings; no one setting is the complete canonical occupation.','entry_level_basis','The reviewed Japanese social-work programme is retained as a direct study pathway, while statutory subject and examination requirements still apply.','qualification_note','社会福祉士 is a protected national title requiring eligibility, the national examination and registration.','market_scope','Setting-specific welfare classifications are not merged into one unsupported exact social-worker market series.','visa_scope','No occupation-specific visa credit is assigned.'),'2026-08-10'),
('JP:youth-worker','2026-08-10',0,0,0,0,10,0,0,0,3,13,'career-opportunity-jp-v1','provisional',jsonb_build_object('classification_scope','The broad Youth Worker career spans 030-02 児童館指導員 and 049-05 児童福祉施設指導専門員 youth-support scopes rather than one universal occupation code.','entry_level_basis','The reviewed social-work programme is retained only as related. Youth-support roles can be entered through social welfare, psychology, education or supervised child-welfare experience depending on the setting.','qualification_note','There is no single universal Youth Worker licence. Specific 児童指導員 positions require an appointment qualification and particular facilities can impose additional staffing standards.','market_scope','Child-center and child-welfare-facility classifications are not merged into a fabricated exact youth-worker market series.','visa_scope','No occupation-specific visa credit is assigned.'),'2026-08-10'),
('JP:community-worker','2026-08-10',0,0,0,0,15,0,0,0,5,20,'career-opportunity-jp-v1','provisional',jsonb_build_object('classification_scope','2022 MHLW 049-99 explicitly includes 社会福祉協議会相談員 and 福祉活動専門員, which provide the closest community-welfare anchor for the canonical Community Worker role.','entry_level_basis','Social work and broader social/human studies can support entry; the four reviewed Japanese programme mappings remain related rather than occupational qualification.','qualification_note','No universal personal Community Worker licence applies. Some municipal or statutory welfare posts can require a 社会福祉主事 appointment qualification or other role-specific criteria.','market_scope','Community and statutory welfare roles vary by employer, so no broader welfare market data are scored as exact Community Worker evidence.','visa_scope','No occupation-specific visa credit is assigned.'),'2026-08-10'),
('JP:counsellor','2026-08-10',0,0,0,0,12,0,0,0,4,16,'career-opportunity-jp-v1','provisional',jsonb_build_object('classification_scope','2022 MHLW 019-03 directly covers counsellors outside medical and welfare facilities, including school, career, workplace and private-practice counselling; medical and welfare counselling is classified separately under 027-99 and 049-99.','entry_level_basis','Psychology and human-sciences study are relevant but the two reviewed Japanese programmes are retained only as related pathways.','qualification_note','Counsellor is not one universally licensed occupation. Specific protected titles such as 公認心理師 and キャリアコンサルタント require their own registration, and many school or clinical counselling posts expect recognised credentials.','market_scope','Medical, welfare and non-medical counselling classifications are not merged into a fabricated exact counsellor market series.','visa_scope','No occupation-specific visa credit is assigned.'),'2026-08-10')
